"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import type { Outfit, Product } from "@/lib/types"
import { ShoppingBag, MapPin, Plus, Heart, Share2, ChevronLeft, ChevronRight, Eye } from "lucide-react"

interface OutfitCardProps {
  outfit: Outfit
  onProductClick?: (product: Product) => void
  onShopLook?: (outfit: Outfit) => void
  onViewDetails?: (outfit: Outfit) => void
  onClick?: () => void
  className?: string
}

function OutfitCard({ outfit, onProductClick, onShopLook, onViewDetails, onClick, className }: OutfitCardProps) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0)
  const [isLiked, setIsLiked] = useState(false)

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % outfit.items.length)
  }

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + outfit.items.length) % outfit.items.length)
  }

  const getAvailabilityColor = (availability: Product["availability"]) => {
    switch (availability) {
      case "in_stock":
        return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"
      case "low_stock":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200"
      case "out_of_stock":
        return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200"
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200"
    }
  }

  const getAvailabilityText = (availability: Product["availability"]) => {
    switch (availability) {
      case "in_stock":
        return "In Stock"
      case "low_stock":
        return "Low Stock"
      case "out_of_stock":
        return "Out of Stock"
      default:
        return "Unknown"
    }
  }

  return (
    <Card
      className={`overflow-hidden animate-fade-in-up ${onClick ? 'cursor-pointer hover:shadow-lg transition-shadow' : ''} ${className}`}
      role="article"
      aria-label={`Outfit: ${outfit.title}`}
      onClick={onClick}
    >
      <CardContent className="p-0">
        {/* Hero Image Section */}
        <div className="relative aspect-[3/4] bg-muted">
          <img
            src={outfit.imageUrl || "/placeholder.svg?height=400&width=320"}
            alt={outfit.title}
            className="w-full h-full object-cover"
            loading="lazy"
            onError={(e) => {
              e.currentTarget.src = "/placeholder.svg?height=400&width=320"
            }}
          />

          {/* Image Navigation */}
          {outfit.items.length > 1 && (
            <>
              <Button
                size="sm"
                variant="secondary"
                className="absolute left-2 top-1/2 -translate-y-1/2 h-8 w-8 p-0 rounded-full bg-background/80 backdrop-blur"
                onClick={prevImage}
              >
                <ChevronLeft className="w-4 h-4" />
              </Button>
              <Button
                size="sm"
                variant="secondary"
                className="absolute right-2 top-1/2 -translate-y-1/2 h-8 w-8 p-0 rounded-full bg-background/80 backdrop-blur"
                onClick={nextImage}
              >
                <ChevronRight className="w-4 h-4" />
              </Button>
            </>
          )}

          {/* Action Buttons */}
          <div className="absolute top-3 right-3 flex gap-2">
            <Button
              size="sm"
              variant="secondary"
              className="h-8 w-8 p-0 rounded-full bg-white/90 hover:bg-white backdrop-blur border border-gray-200 shadow-sm"
              onClick={() => setIsLiked(!isLiked)}
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
              aria-pressed={isLiked}
            >
              <Heart className={`w-5 h-5 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600 hover:text-gray-800"}`} />
            </Button>
            <Button
              size="sm"
              variant="secondary"
              className="h-8 w-8 p-0 rounded-full bg-white/90 hover:bg-white backdrop-blur border border-gray-200 shadow-sm"
              aria-label="Share outfit"
            >
              <Share2 className="w-5 h-5 text-gray-600 hover:text-gray-800" />
            </Button>
          </div>

          {/* Image Indicators */}
          {outfit.items.length > 1 && (
            <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1">
              {outfit.items.map((_, index) => (
                <button
                  key={index}
                  className="image-indicator"
                  onClick={() => setCurrentImageIndex(index)}
                  aria-label={`View item ${index + 1}`}
                >
                  <div
                    className={`w-2 h-2 rounded-full transition-colors ${
                      index === currentImageIndex ? "bg-white" : "bg-white/50"
                    }`}
                  />
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="p-3 md:p-4 space-y-3 md:space-y-4">
          {/* Title and Price Section - Fixed layout */}
          <div className="space-y-2">
            <div className="flex items-start gap-4">
              <div className="flex-1 min-w-0">
                <h3 className="font-bold text-xs md:text-sm text-balance leading-tight line-clamp-2">
                  {outfit.title}
                </h3>
                <p className="text-muted-foreground text-[11px] md:text-xs text-pretty mt-1 line-clamp-2">
                  {outfit.description}
                </p>
              </div>
              <div className="text-right flex-shrink-0">
                <p className="text-base md:text-lg font-bold">฿{outfit.totalPrice.toLocaleString()}</p>
                <p className="text-[10px] md:text-xs text-muted-foreground whitespace-nowrap mt-0.5">{outfit.items.length} items</p>
              </div>
            </div>
          </div>

          {/* Product Items Section - Improved spacing */}
          <div className="space-y-2 md:space-y-3">
            <h4 className="text-[11px] md:text-xs font-semibold">Items in this look:</h4>
            <div className="flex gap-2 md:gap-3 overflow-x-auto pb-2 -mx-1 px-1 scrollbar-hide">
              {outfit.items.map((product) => (
                <div
                  key={product.sku}
                  className="flex-shrink-0 w-24 md:w-28 cursor-pointer group"
                  onClick={() => onProductClick?.(product)}
                >
                  <div className="relative">
                    <div className="aspect-square w-full rounded-lg overflow-hidden bg-muted">
                      <img
                        src={product.imageUrl || "/placeholder.svg"}
                        alt={product.name}
                        className="w-full h-full object-cover group-hover:scale-105 transition-transform"
                        loading="lazy"
                        onError={(e) => {
                          e.currentTarget.src = "/placeholder.svg"
                        }}
                      />
                    </div>
                    <Badge
                      className={`absolute top-1 right-1 text-[10px] md:text-xs px-1.5 md:px-2 py-0.5 ${getAvailabilityColor(product.availability)}`}
                    >
                      {getAvailabilityText(product.availability)}
                    </Badge>
                  </div>
                  <div className="mt-1.5 md:mt-2 space-y-0.5">
                    <p className="text-[9px] md:text-[10px] font-medium text-balance leading-tight line-clamp-2">
                      {product.name}
                    </p>
                    <p className="text-[9px] md:text-[10px] text-muted-foreground line-clamp-1">{product.brand}</p>
                    <p className="text-[10px] md:text-xs font-bold">฿{product.price.toLocaleString()}</p>
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full mt-1.5 md:mt-2 h-6 md:h-7 text-[10px] md:text-xs bg-transparent"
                    disabled={product.availability === "out_of_stock"}
                  >
                    <Eye className="w-3 md:w-3.5 h-3 md:h-3.5 mr-1" />
                    View Look
                  </Button>
                </div>
              ))}
            </div>
          </div>

          {/* Action Buttons - Improved responsive sizing */}
          <div className="flex gap-2">
            {onViewDetails && (
              <Button
                variant="outline"
                className="flex-1 h-9 md:h-10 text-xs md:text-sm bg-transparent"
                onClick={() => onViewDetails(outfit)}
              >
                View Details
              </Button>
            )}
            <Button
              className={`${onViewDetails ? 'flex-1' : 'flex-1'} h-9 md:h-10 text-xs md:text-sm`}
              onClick={() => onShopLook?.(outfit)}
            >
              <ShoppingBag className="w-4 h-4 mr-2" />
              Shop Look
            </Button>
            <Button variant="outline" size="sm" className="px-2.5 md:px-3 h-9 md:h-10 bg-transparent flex-shrink-0">
              <MapPin className="w-4 h-4" />
            </Button>
          </div>

          {/* Store Availability - Only show if locations exist */}
          {(() => {
            const storeLocations = Array.from(new Set(outfit.items.flatMap((item) => item.storeLocations || [])))
            // If no locations from data, use default Central locations
            const locations = storeLocations.length > 0 ? storeLocations : ['Central Chidlom', 'Central World', 'Central Ladprao']

            return (
              <div className="pt-3 md:pt-4 border-t space-y-2.5">
                <p className="text-xs text-muted-foreground">Available at:</p>
                <div className="flex flex-wrap gap-1.5">
                  {locations.map((location) => (
                    <Badge key={location} variant="secondary" className="text-xs px-2 py-0.5">
                      {location}
                    </Badge>
                  ))}
                </div>
              </div>
            )
          })()}
        </div>
      </CardContent>
    </Card>
  )
}

export default OutfitCard
export { OutfitCard }

'use client'

import { Button } from '@/components/ui/button'
import { OutfitProductList } from './OutfitProductList'
import { StickyPurchaseSection } from './StickyPurchaseSection'
import { SimilarOutfits } from './SimilarOutfits'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import type { Outfit, Product } from '@/lib/types'
import { ArrowLeft } from 'lucide-react'

interface OutfitDetailProps {
  outfit: Outfit
  similarOutfits?: Outfit[]
  onBack: () => void
  onBuyProduct: (product: Product) => void
  onBuyAll: () => void
  onSelectSimilar?: (outfit: Outfit) => void
}

export function OutfitDetail({
  outfit,
  similarOutfits = [],
  onBack,
  onBuyProduct,
  onBuyAll,
  onSelectSimilar
}: OutfitDetailProps) {
  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  if (!outfit) return null

  return (
    <div className="h-full flex flex-col">
      {/* Header with back button and resize controls */}
      <div className="border-b px-4 py-3">
        <div className="flex items-center justify-between mb-2">
          <Button
            variant="ghost"
            onClick={onBack}
            className="-ml-2"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Explore more outfits
          </Button>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      </div>

      {/* Scrollable content */}
      <div className="flex-1 overflow-y-auto">
        <div className="p-4">
          {/* Outfit title and occasion */}
          <h2 className="text-lg font-bold mb-1 text-foreground">{outfit.title}</h2>
          <p className="text-xs text-gray-600 dark:text-gray-400 mb-4">
            {outfit.description || 'Office wear'}
          </p>

          {/* Outfit preview image */}
          <div className="aspect-[3/4] bg-gray-100 rounded-lg mb-4 overflow-hidden">
            {outfit.imageUrl ? (
              <img
                src={outfit.imageUrl}
                alt={outfit.title}
                className="w-full h-full object-cover"
              />
            ) : (
              <div className="w-full h-full bg-gray-300" />
            )}
          </div>

          {/* Product list */}
          <OutfitProductList
            products={outfit.items}
            onBuyProduct={onBuyProduct}
          />

          {/* Similar outfits */}
          {onSelectSimilar && (
            <SimilarOutfits
              outfits={similarOutfits}
              onSelectOutfit={onSelectSimilar}
            />
          )}
        </div>
      </div>

      {/* Sticky purchase section */}
      <StickyPurchaseSection
        totalPrice={outfit.totalPrice}
        onBuyAll={onBuyAll}
      />
    </div>
  )
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogClose,
} from "@/components/ui/dialog"
import type { Outfit, Product } from "@/lib/types"
import {
  ShoppingBag,
  MapPin,
  Heart,
  Share2,
  X,
  ChevronLeft,
  ChevronRight,
  Plus,
  Minus,
} from "lucide-react"

interface OutfitDetailsProps {
  outfit: Outfit | null
  isOpen: boolean
  onClose: () => void
  onProductClick?: (product: Product) => void
  onShopLook?: (outfit: Outfit) => void
}

export default function OutfitDetails({
  outfit,
  isOpen,
  onClose,
  onProductClick,
  onShopLook,
}: OutfitDetailsProps) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0)
  const [isLiked, setIsLiked] = useState(false)
  const [quantities, setQuantities] = useState<Record<string, number>>({})

  if (!outfit) return null

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % outfit.items.length)
  }

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + outfit.items.length) % outfit.items.length)
  }

  const updateQuantity = (sku: string, change: number) => {
    setQuantities((prev) => ({
      ...prev,
      [sku]: Math.max(0, (prev[sku] || 1) + change),
    }))
  }

  const getAvailabilityColor = (availability: Product["availability"]) => {
    switch (availability) {
      case "in_stock":
        return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"
      case "low_stock":
        return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200"
      case "out_of_stock":
        return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200"
      default:
        return "bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200"
    }
  }

  const getAvailabilityText = (availability: Product["availability"]) => {
    switch (availability) {
      case "in_stock":
        return "In Stock"
      case "low_stock":
        return "Low Stock"
      case "out_of_stock":
        return "Out of Stock"
      default:
        return "Unknown"
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-6xl w-[95vw] max-h-[95vh] overflow-hidden p-0 m-4">
        <div className="flex flex-col lg:flex-row h-full max-h-[95vh]">
          {/* Image Section */}
          <div className="relative lg:w-1/2 bg-muted">
            <div className="relative aspect-[4/5] lg:aspect-[3/4] lg:h-[85vh]">
              <img
                src={outfit.imageUrl || "/placeholder.svg?height=600&width=480"}
                alt={outfit.title}
                className="w-full h-full object-cover"
              />

              {/* Image Navigation */}
              {outfit.items.length > 1 && (
                <>
                  <Button
                    size="sm"
                    variant="secondary"
                    className="absolute left-3 top-1/2 -translate-y-1/2 h-10 w-10 p-0 rounded-full bg-background/90 backdrop-blur shadow-lg"
                    onClick={prevImage}
                    aria-label="Previous image"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </Button>
                  <Button
                    size="sm"
                    variant="secondary"
                    className="absolute right-3 top-1/2 -translate-y-1/2 h-10 w-10 p-0 rounded-full bg-background/90 backdrop-blur shadow-lg"
                    onClick={nextImage}
                    aria-label="Next image"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </Button>
                </>
              )}

              {/* Action Buttons */}
              <div className="absolute top-4 right-4 flex gap-2">
                <Button
                  size="sm"
                  variant="secondary"
                  className="h-10 w-10 p-0 rounded-full bg-background/90 backdrop-blur shadow-lg"
                  onClick={() => setIsLiked(!isLiked)}
                  aria-label={isLiked ? "Remove from favorites" : "Add to favorites"}
                >
                  <Heart className={`w-5 h-5 ${isLiked ? "fill-red-500 text-red-500" : ""}`} />
                </Button>
                <Button
                  size="sm"
                  variant="secondary"
                  className="h-10 w-10 p-0 rounded-full bg-background/90 backdrop-blur shadow-lg"
                  aria-label="Share outfit"
                >
                  <Share2 className="w-5 h-5" />
                </Button>
                <DialogClose asChild>
                  <Button
                    size="sm"
                    variant="secondary"
                    className="h-10 w-10 p-0 rounded-full bg-background/90 backdrop-blur shadow-lg"
                    aria-label="Close"
                  >
                    <X className="w-5 h-5" />
                  </Button>
                </DialogClose>
              </div>

              {/* Image Indicators */}
              {outfit.items.length > 1 && (
                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2">
                  {outfit.items.map((_, index) => (
                    <button
                      key={index}
                      className={`w-2 h-2 rounded-full transition-colors ${
                        index === currentImageIndex ? "bg-white" : "bg-white/50"
                      }`}
                      onClick={() => setCurrentImageIndex(index)}
                      aria-label={`View image ${index + 1}`}
                    />
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Content Section */}
          <div className="lg:w-1/2 flex flex-col min-h-0">
            <DialogHeader className="p-4 lg:p-6 pb-3 lg:pb-4 border-b shrink-0">
              <DialogTitle className="text-xl lg:text-2xl font-bold text-left">
                {outfit.title}
              </DialogTitle>
              <div className="flex items-center justify-between mt-2">
                <p className="text-2xl lg:text-3xl font-bold text-primary">
                  ฿{outfit.totalPrice.toLocaleString()}
                </p>
                <p className="text-sm text-muted-foreground">
                  {outfit.items.length} items
                </p>
              </div>
              <DialogDescription className="text-muted-foreground text-left mt-2 text-sm lg:text-base">
                {outfit.description}
              </DialogDescription>
            </DialogHeader>

            {/* Scrollable Product List */}
            <div className="flex-1 overflow-y-auto p-4 lg:p-6 min-h-0">
              <h3 className="font-semibold mb-4 text-base lg:text-lg">Items in this outfit:</h3>
              <div className="space-y-4">
                {outfit.items.map((product) => {
                  const quantity = quantities[product.sku] || 1
                  return (
                    <div
                      key={product.sku}
                      className="flex gap-3 sm:gap-4 p-3 sm:p-4 border rounded-lg hover:border-gray-300 transition-colors"
                    >
                      <div
                        className="relative w-20 h-20 sm:w-24 sm:h-24 flex-shrink-0 cursor-pointer group"
                        onClick={() => onProductClick?.(product)}
                      >
                        <img
                          src={product.imageUrl || "/placeholder.svg"}
                          alt={product.name}
                          className="w-full h-full object-cover rounded-lg bg-muted group-hover:scale-105 transition-transform"
                        />
                        <Badge
                          className={`absolute top-1 right-1 text-xs px-1.5 py-0.5 ${getAvailabilityColor(product.availability)}`}
                        >
                          {getAvailabilityText(product.availability)}
                        </Badge>
                      </div>

                      <div className="flex-1 min-w-0">
                        <h4 className="font-medium text-sm sm:text-base leading-tight line-clamp-2">
                          {product.name}
                        </h4>
                        <p className="text-sm text-muted-foreground mt-1">
                          {product.brand}
                        </p>
                        <p className="text-lg sm:text-xl font-bold mt-2">
                          ฿{product.price.toLocaleString()}
                        </p>

                        {/* Size and Color Options */}
                        {(product.sizes || product.colors) && (
                          <div className="mt-3 space-y-2">
                            {product.sizes && (
                              <div>
                                <p className="text-xs text-muted-foreground mb-1">Sizes:</p>
                                <div className="flex gap-1 flex-wrap">
                                  {product.sizes.map((size) => (
                                    <Badge key={size} variant="outline" className="text-xs">
                                      {size}
                                    </Badge>
                                  ))}
                                </div>
                              </div>
                            )}
                            {product.colors && (
                              <div>
                                <p className="text-xs text-muted-foreground mb-1">Colors:</p>
                                <div className="flex gap-1 flex-wrap">
                                  {product.colors.map((color) => (
                                    <Badge key={color} variant="outline" className="text-xs">
                                      {color}
                                    </Badge>
                                  ))}
                                </div>
                              </div>
                            )}
                          </div>
                        )}

                        {/* Quantity Selector */}
                        <div className="flex items-center gap-2 mt-3">
                          <div className="flex items-center border rounded">
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-9 w-9 sm:h-8 sm:w-8 p-0 rounded-none"
                              onClick={() => updateQuantity(product.sku, -1)}
                              disabled={quantity <= 1}
                              aria-label="Decrease quantity"
                            >
                              <Minus className="w-4 h-4 sm:w-3 sm:h-3" />
                            </Button>
                            <span className="px-3 py-2 sm:py-1 text-sm min-w-[3rem] text-center">
                              {quantity}
                            </span>
                            <Button
                              size="sm"
                              variant="ghost"
                              className="h-9 w-9 sm:h-8 sm:w-8 p-0 rounded-none"
                              onClick={() => updateQuantity(product.sku, 1)}
                              aria-label="Increase quantity"
                            >
                              <Plus className="w-4 h-4 sm:w-3 sm:h-3" />
                            </Button>
                          </div>
                          <Button
                            size="sm"
                            variant="outline"
                            className="flex-1 bg-transparent h-9 sm:h-8"
                            disabled={product.availability === "out_of_stock"}
                            onClick={() => onProductClick?.(product)}
                          >
                            <Plus className="w-4 h-4 sm:w-3 sm:h-3 mr-1" />
                            Add to Cart
                          </Button>
                        </div>
                      </div>
                    </div>
                  )
                })}
              </div>

              {/* Store Availability */}
              <div className="mt-6 pt-4 border-t">
                <h3 className="font-semibold mb-3">Available at:</h3>
                <div className="flex flex-wrap gap-2">
                  {Array.from(new Set(outfit.items.flatMap((item) => item.storeLocations || []))).map((location) => (
                    <Badge key={location} variant="secondary" className="text-sm px-3 py-1">
                      <MapPin className="w-3 h-3 mr-1" />
                      {location}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>

            {/* Action Footer */}
            <div className="p-4 lg:p-6 border-t bg-muted/30 shrink-0">
              <div className="flex gap-3">
                <Button
                  className="flex-1 h-10 lg:h-12 text-sm lg:text-base"
                  onClick={() => outfit && onShopLook?.(outfit)}
                >
                  <ShoppingBag className="w-4 h-4 lg:w-5 lg:h-5 mr-2" />
                  Shop Complete Look
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  className="px-3 lg:px-4 h-10 lg:h-12 bg-transparent"
                  aria-label="Find in store"
                >
                  <MapPin className="w-4 h-4 lg:w-5 lg:h-5" />
                </Button>
              </div>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import type { Outfit } from '@/lib/types'
import { Card } from '@/components/ui/card'

interface SimilarOutfitsProps {
  outfits: Outfit[]
  onSelectOutfit: (outfit: Outfit) => void
}

export function SimilarOutfits({ outfits, onSelectOutfit }: SimilarOutfitsProps) {
  if (outfits.length === 0) return null

  return (
    <div className="mt-6 pb-4">
      <h3 className="font-medium mb-3">Similar outfits</h3>

      <div className="grid grid-cols-2 gap-3">
        {outfits.slice(0, 6).map((outfit) => (
          <Card
            key={outfit.id}
            className="cursor-pointer hover:shadow-md transition-shadow overflow-hidden"
            onClick={() => onSelectOutfit(outfit)}
          >
            <div className="aspect-[3/4] bg-gray-100">
              {outfit.imageUrl ? (
                <img
                  src={outfit.imageUrl}
                  alt={outfit.title}
                  className="w-full h-full object-cover"
                />
              ) : (
                <div className="w-full h-full bg-gray-300" />
              )}
            </div>

            <div className="p-2">
              <p className="text-xs font-medium line-clamp-1">{outfit.title}</p>
              <p className="text-xs text-primary font-bold mt-1">
                ฿{outfit.totalPrice.toLocaleString()}
              </p>
            </div>
          </Card>
        ))}
      </div>
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import Image from 'next/image'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import type { Outfit } from '@/lib/types'
import { useUserProfile } from '@/lib/hooks/useUserProfile'
import { generateTryOnLooks } from '@/lib/services/fitting-model-service'
import { Eye, Heart, Share2, Shirt, Loader2, RefreshCw, AlertCircle } from 'lucide-react'

interface OutfitRecommendationCardProps {
  outfit: Outfit
  onViewOutfit: (outfit: Outfit) => void
}

export function OutfitRecommendationCard({
  outfit,
  onViewOutfit
}: OutfitRecommendationCardProps) {
  const [isLiked, setIsLiked] = useState(false)
  const [imageError, setImageError] = useState(false)

  // Try-on state
  const [showTryOnModal, setShowTryOnModal] = useState(false)
  const [isGeneratingTryOn, setIsGeneratingTryOn] = useState(false)
  const [tryOnImageUrl, setTryOnImageUrl] = useState<string | undefined>(outfit.tryOnImageUrl)
  const [tryOnImageBase64, setTryOnImageBase64] = useState<string | undefined>(outfit.tryOnImageBase64)
  const [tryOnError, setTryOnError] = useState<string | undefined>()

  // Get user profile for fitting model
  const { profile } = useUserProfile()

  // Check if user has a fitting model
  const hasFittingModel = !!profile?.fittingModelUrl

  // Determine image source: prefer flat-lay, fallback to product thumbnail
  const flatLayImage = outfit.flatLayImageUrl || outfit.flatLayImageBase64
  const fallbackImage = outfit.imageUrl
  const displayImage = flatLayImage || fallbackImage
  const isGenerating = outfit.isGeneratingFlatLay

  // Try-on image to display
  const tryOnImage = tryOnImageUrl || tryOnImageBase64

  // Sync with outfit prop when it changes
  useEffect(() => {
    if (outfit.tryOnImageUrl) {
      setTryOnImageUrl(outfit.tryOnImageUrl)
    }
    if (outfit.tryOnImageBase64) {
      setTryOnImageBase64(outfit.tryOnImageBase64)
    }
  }, [outfit.tryOnImageUrl, outfit.tryOnImageBase64])

  /**
   * Handle try-on button click
   */
  const handleTryOn = useCallback(async () => {
    // If we already have a try-on image, just open the modal
    if (tryOnImage) {
      setShowTryOnModal(true)
      return
    }

    // Check if user has a fitting model
    if (!hasFittingModel || !profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setShowTryOnModal(true)
      return
    }

    // Start generation
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)
    setShowTryOnModal(true)

    try {
      // Extract outfit items for the prompt
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [tryOnImage, hasFittingModel, profile?.fittingModelUrl, outfit])

  /**
   * Handle regenerate try-on image
   */
  const handleRegenerate = useCallback(async () => {
    // Clear current image and regenerate
    setTryOnImageUrl(undefined)
    setTryOnImageBase64(undefined)
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)

    if (!profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setIsGeneratingTryOn(false)
      return
    }

    try {
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Regenerate error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [profile?.fittingModelUrl, outfit])

  return (
    <>
      <Card className="p-3 bg-white/10 backdrop-blur-sm hover:bg-white/20 transition-colors overflow-hidden">
        {/* Flat-lay image area (square aspect ratio) */}
        <div className="relative w-full aspect-square bg-gray-100 rounded-lg overflow-hidden mb-3">
          {isGenerating ? (
            // Loading skeleton while flat-lay is generating
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <Skeleton className="w-full h-full absolute inset-0" />
              <div className="z-10 text-center px-4">
                <div className="flex justify-center mb-2">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                  </div>
                </div>
                <p className="text-xs text-gray-500">กำลังสร้างภาพ LOOKs...</p>
              </div>
            </div>
          ) : displayImage && !imageError ? (
            // Show flat-lay or fallback image
            <Image
              src={displayImage}
              alt={outfit.title}
              fill
              className={flatLayImage ? 'object-contain' : 'object-cover'}
              sizes="(max-width: 768px) 100vw, 400px"
              onError={() => setImageError(true)}
            />
          ) : (
            // Placeholder when no image available
            <div className="w-full h-full flex items-center justify-center bg-gray-200">
              <span className="text-gray-400 text-sm">No image</span>
            </div>
          )}
        </div>

        {/* Card content */}
        <div className="space-y-2">
          <div>
            <h4 className="font-semibold text-sm line-clamp-2">{outfit.title}</h4>
            <p className="text-xs text-muted-foreground mt-0.5">
              {outfit.items.length} ชิ้น
            </p>
          </div>

          <p className="text-base font-bold">
            ฿{outfit.totalPrice.toLocaleString()}
          </p>

          {/* Action Icons Row */}
          <div className="flex items-center gap-1.5">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => onViewOutfit(outfit)}
              className="flex-1 h-8 text-xs gap-1"
            >
              <Eye className="w-3.5 h-3.5" />
              ดูลุค
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleTryOn}
              disabled={isGeneratingTryOn}
              className="h-8 px-2 text-xs gap-1"
              aria-label="ลองใส่ outfit นี้"
              title={hasFittingModel ? 'ลองใส่' : 'กรุณาอัปโหลดรูปภาพก่อน'}
            >
              {isGeneratingTryOn ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Shirt className="w-3.5 h-3.5" />
              )}
              ลองใส่
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setIsLiked(!isLiked)}
              className="h-8 w-8 p-0"
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
            >
              <Heart className={`w-4 h-4 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600"}`} />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              className="h-8 w-8 p-0"
              aria-label="Share outfit"
            >
              <Share2 className="w-4 h-4 text-gray-600" />
            </Button>
          </div>
        </div>
      </Card>

      {/* Try-On Modal */}
      <Dialog open={showTryOnModal} onOpenChange={setShowTryOnModal}>
        <DialogContent className="max-w-md mx-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shirt className="w-5 h-5" />
              ลองใส่: {outfit.title}
            </DialogTitle>
            <DialogDescription>
              ดูชุดนี้บนโมเดลของคุณ
            </DialogDescription>
          </DialogHeader>

          {/* Try-On Image Area */}
          <div className="relative w-full aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden">
            {isGeneratingTryOn ? (
              // Loading state
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <Skeleton className="w-full h-full absolute inset-0" />
                <div className="z-10 text-center px-4">
                  <div className="flex justify-center mb-3">
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  </div>
                  <p className="text-sm text-gray-600 font-medium">กำลังสร้างรูปภาพ...</p>
                  <p className="text-xs text-gray-400 mt-1">อาจใช้เวลา 10-30 วินาที</p>
                </div>
              </div>
            ) : tryOnError ? (
              // Error state
              <div className="absolute inset-0 flex flex-col items-center justify-center p-4">
                <div className="text-center">
                  <AlertCircle className="w-12 h-12 text-red-400 mx-auto mb-3" />
                  <p className="text-sm text-gray-600 mb-4">{tryOnError}</p>
                  {hasFittingModel && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={handleRegenerate}
                      className="gap-2"
                    >
                      <RefreshCw className="w-4 h-4" />
                      ลองอีกครั้ง
                    </Button>
                  )}
                </div>
              </div>
            ) : tryOnImage ? (
              // Show try-on image
              <Image
                src={tryOnImage}
                alt={`ลองใส่: ${outfit.title}`}
                fill
                className="object-contain"
                sizes="(max-width: 768px) 100vw, 400px"
              />
            ) : (
              // Empty state (should not happen normally)
              <div className="w-full h-full flex items-center justify-center bg-gray-200">
                <span className="text-gray-400 text-sm">ไม่มีรูปภาพ</span>
              </div>
            )}
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 mt-2">
            {tryOnImage && !isGeneratingTryOn && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleRegenerate}
                className="flex-1 gap-2"
              >
                <RefreshCw className="w-4 h-4" />
                ลองใส่ใหม่
              </Button>
            )}
            <Button
              size="sm"
              variant="default"
              onClick={() => setShowTryOnModal(false)}
              className="flex-1"
            >
              ปิด
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { ChatHeader } from './ChatHeader'
import { ChatMessage } from './ChatMessage'
import { ChatInput } from './ChatInput'
import { QuickPrompts } from './QuickPrompts'
import { OutfitRecommendationCard } from './OutfitRecommendationCard'
import { InteractiveTestMode } from './InteractiveTestMode'
import { Button } from '@/components/ui/button'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import { Beaker } from 'lucide-react'
import type { ChatMessage as ChatMessageType, Outfit, FlatLayItem } from '@/lib/types'
import type { TestResult } from '@/lib/types/test-types'
import { getMockOutfitResponse } from '@/lib/mock-data'
import { exportResultsBoth } from '@/lib/test-result-exporter'
import type { SessionContext } from '@/lib/types/chat-types'
import { createSessionContext } from '@/lib/utils/session-context'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

interface ChatAssistantProps {
  onViewOutfit: (outfit: Outfit) => void
}

export function ChatAssistant({ onViewOutfit }: ChatAssistantProps) {
  const [messages, setMessages] = useState<ChatMessageType[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [testMode, setTestMode] = useState(false)

  // v2.0: Session context for duplicate prevention
  const [sessionContext, setSessionContext] = useState<SessionContext>(() => createSessionContext())
  const [conversationId] = useState<string>(() => `conv-${Date.now()}`)

  // v2.4: User profile for gender preference
  const { profile } = useUserProfile()

  // v3.1: Image generation state (Customer Journey Step 4)
  const [generatingImage, setGeneratingImage] = useState(false)
  const [imageGenerationError, setImageGenerationError] = useState<string | null>(null)

  // v3.2: Initialize with Thai greeting message
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: ChatMessageType = {
        id: 'greeting-initial',
        content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
        sender: 'assistant',
        timestamp: new Date(),
      }
      setMessages([greeting])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  const isTestModeEnabled = process.env.NEXT_PUBLIC_ENABLE_TEST_MODE === 'true'

  const handleTestComplete = (result: TestResult) => {
    console.log('Test completed:', result)
  }

  const handleExportResults = (results: TestResult[]) => {
    exportResultsBoth(results)
  }

  /**
   * v5.0: Generate flat-lay image for an outfit and update the message
   * This function is called after outfit recommendations are shown
   */
  const generateFlatLayForOutfit = useCallback(async (outfit: Outfit, messageId: string) => {
    console.log(`[Chat] Generating flat-lay for outfit ${outfit.id}...`)

    // Extract FlatLayItem array from outfit items
    const flatLayItems: FlatLayItem[] = outfit.items.slice(0, 5).map((item: any) => ({
      name: item.name,
      category: item.subCategory || item.category || 'Item',
      color: item.colors?.[0],
      visualDescription: item.visualDescription,
    }))
    const occasionContext = outfit.description

    if (flatLayItems.length === 0) {
      console.log('[Chat] No items to generate flat-lay for')
      return
    }

    try {
      const imageResponse = await fetch('/api/generate-image', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          description: outfit.description || 'LOOKs Inspiration',
          generationType: 'flat-lay',
          flatLayItems,
          occasionContext,
        }),
      })

      const imageData = await imageResponse.json()

      if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
        console.log(`[Chat] Flat-lay generated successfully for outfit ${outfit.id}`)

        // Update the message's outfit with the flat-lay image
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        flatLayImageUrl: imageData.imageUrl,
                        flatLayImageBase64: imageData.imageBase64,
                        isGeneratingFlatLay: false,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      } else {
        console.error('[Chat] Flat-lay generation failed:', imageData.message)
        // Mark as not generating (will show fallback thumbnail)
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id ? { ...o, isGeneratingFlatLay: false } : o
                ),
              }
            }
            return msg
          })
        )
      }
    } catch (error) {
      console.error('[Chat] Flat-lay generation error:', error)
      // Mark as not generating on error
      setMessages((prev) =>
        prev.map((msg) => {
          if (msg.id === messageId && msg.outfits) {
            return {
              ...msg,
              outfits: msg.outfits.map((o) =>
                o.id === outfit.id ? { ...o, isGeneratingFlatLay: false } : o
              ),
            }
          }
          return msg
        })
      )
    }
  }, [])

  const handleSendMessage = async (content: string) => {
    if (!content.trim()) return

    // Add user message
    const userMessage: ChatMessageType = {
      id: `user-${Date.now()}`,
      content: content.trim(),
      sender: 'user',
      timestamp: new Date(),
    }

    setMessages((prev) => [...prev, userMessage])
    setIsTyping(true)

    try {
      // Call real chat API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: content.trim(),
          conversationHistory: messages.map((msg) => ({
            role: msg.sender === 'user' ? 'user' : 'assistant',
            content: msg.content,
          })),
          sessionContext, // v2.0: Send current session context
          conversationId, // v2.0: Send conversation ID
          userPreferences: {
            gender: profile?.gender as 'men' | 'women' | undefined,
            userName: profile?.userName,
            ageRange: profile?.ageRange,
            stylePreferences: profile?.stylePreferences,
          }, // v2.5: Pass detailed profile info
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get response from chat API')
      }

      const data = await response.json()

      // v2.0: Update session context if returned
      if (data.sessionContext) {
        setSessionContext(data.sessionContext)
        console.log(`[Chat] Session updated: ${data.sessionContext.recommendedProductIds?.length || 0} total products recommended`)
      }

      // v5.0: Mark outfits as generating flat-lay if we have image request
      const outfitsWithLoading = (data.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: data.imageRequest && outfit.items.length > 0,
      }))

      // Create AI response message
      const messageId = `ai-${Date.now()}`
      const aiResponse: ChatMessageType = {
        id: messageId,
        content: data.message || 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ',
        sender: 'assistant',
        timestamp: new Date(),
        outfits: outfitsWithLoading,
      }

      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v5.0: Generate flat-lay images for each outfit (embedded in card, no separate message)
      if (data.imageRequest && outfitsWithLoading.length > 0) {
        console.log('[Chat] Image request detected, generating flat-lay for outfit cards...')

        // Add AI acknowledgment message for generation
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        // Generate flat-lay for each outfit
        for (const outfit of outfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    } catch (error) {
      console.error('Chat error:', error)

      // Fallback to mock response on error
      const aiResponse = getMockOutfitResponse(content)
      const messageId = `ai-mock-${Date.now()}`

      // v5.0: Mark mock outfits as generating flat-lay
      const mockOutfitsWithLoading = (aiResponse.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: outfit.items.length > 0,
      }))

      const mockMessage: ChatMessageType = {
        ...aiResponse,
        id: messageId,
        outfits: mockOutfitsWithLoading,
      }

      setMessages((prev) => [...prev, mockMessage])
      setIsTyping(false)

      // v5.0: Auto-generate flat-lay for mock responses
      if (mockOutfitsWithLoading.length > 0) {
        console.log('[Chat] Fallback: Auto-generating flat-lay for mock response...')

        // Add acknowledgement
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        for (const outfit of mockOutfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    }
  }

  return (
    <div className="h-full flex flex-col">
      {/* Test Mode Header */}
      {isTestModeEnabled && (
        <div className={`border-b px-4 py-3 flex items-center justify-between ${testMode ? 'bg-orange-50' : ''}`}>
          <div className="flex items-center gap-2">
            {testMode && (
              <span className="px-3 py-1 bg-orange-500 text-white font-bold rounded-md text-sm flex items-center gap-1">
                <Beaker className="w-4 h-4" />
                TEST MODE
              </span>
            )}
            <span className="text-sm text-muted-foreground">
              {testMode ? 'LLM Model Testing Interface' : 'OOTDay Stylist'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
            <Button
              size="sm"
              variant={testMode ? "primary" : "outline"}
              onClick={() => setTestMode(!testMode)}
              className={testMode ? "bg-orange-600 hover:bg-orange-700" : ""}
            >
              <Beaker className="w-4 h-4 mr-2" />
              {testMode ? 'Exit Test Mode' : 'Test Mode'}
            </Button>
          </div>
        </div>
      )}

      {/* Regular Header with resize controls */}
      {!isTestModeEnabled && !testMode && (
        <div className="border-b px-4 py-3 flex items-center justify-between">
          <span className="text-sm font-medium">OOTDay Stylist</span>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      )}

      {/* Interactive Test Mode - Full Screen */}
      {testMode && isTestModeEnabled && (
        <div className="flex-1 overflow-hidden">
          <InteractiveTestMode onExport={handleExportResults} />
        </div>
      )}

      {!testMode && <ChatHeader />}

      {/* Messages Area */}
      {!testMode && (
        <div className="flex-1 overflow-y-auto px-4 py-3">
          {messages.length === 0 && (
            <div className="text-center py-8">
              <p className="text-sm text-muted-foreground leading-relaxed max-w-xs mx-auto">
                สวัสดีค่ะ! OOTDay Stylist พร้อมช่วยหาลุคที่ใช่สำหรับคุณค่ะ ✨
              </p>
            </div>
          )}

          {messages.map((message) => (
            <div key={message.id}>
              <ChatMessage message={message} />

              {/* Outfit recommendations with embedded flat-lay images */}
              {message.outfits && message.outfits.length > 0 && (
                <div className="ml-10 mt-2 space-y-2">
                  {message.outfits.map((outfit) => (
                    <OutfitRecommendationCard
                      key={outfit.id}
                      outfit={outfit}
                      onViewOutfit={onViewOutfit}
                    />
                  ))}
                </div>
              )}
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="flex items-center gap-2 bg-gray-100 rounded-lg px-3 py-2">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Quick Prompts */}
      {!testMode && <QuickPrompts onPromptClick={handleSendMessage} />}

      {/* Chat Input */}
      {!testMode && <ChatInput onSend={handleSendMessage} disabled={isTyping} />}
    </div>
  )
}

